package dev.exodus.teleporter.client;import dev.exodus.ExodusMod;import dev.exodus.teleporter.ExodusTeleporterRegistry;import net.minecraft.client.gui.screens.MenuScreens;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;import net.minecraftforge.fml.event.lifecycle.FMLClientSetupEvent;@Mod.EventBusSubscriber(modid=ExodusMod.MOD_ID,bus=Mod.EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public final class ExodusTeleporterClient{@SubscribeEvent public static void setup(FMLClientSetupEvent e){e.enqueueWork(()->MenuScreens.register(ExodusTeleporterRegistry.TELEPORTER_MENU.get(),ExodusTeleporterScreen::new));}}
